{
  "scene": {
    "id": "node-structure",
    "kind": "content",
    "headline": "AVL树的节点结构：存储高度而非平衡因子",
    "lead": "每个AVL节点存储键值、左右孩子指针和高度（height），通过高度可随时计算平衡因子，避免直接存储平衡因子带来的更新复杂性。",
    "brief": "本页目标：学生能设计AVL树的节点结构并解释为什么存储高度而非平衡因子。核心主张：存储高度可以方便地计算平衡因子，且更新简单。",
    "notes": "介绍工程实现中的节点设计，强调存储高度的原因，纠正直接存储平衡因子的误解。",
    "blocks": [
      {
        "id": "ns-freeform",
        "type": "freeform",
        "role": "demonstrative",
        "intent": "以可视化方式展示AVL节点结构，包含key、left、right、height字段，帮助学生直观理解节点组成。",
        "size": "medium"
      },
      {
        "id": "ns-callout",
        "type": "callout",
        "role": "explanatory",
        "intent": "解释为什么存储高度而非平衡因子：高度更新简单（公式height=1+max(left.height, right.height)），平衡因子可随时计算（balance=left.height-right.height），直接存储平衡因子在旋转时需要同时更新多个节点，容易出错。",
        "size": "small"
      },
      {
        "id": "ns-code",
        "type": "code",
        "role": "reference",
        "intent": "提供AVL节点结构的C语言定义，作为实现参考，强调height字段。",
        "size": "medium"
      }
    ],
    "layout": {
      "kind": "index",
      "steps": [
        {
          "label": "节点结构图",
          "blockIds": ["ns-freeform"]
        },
        {
          "label": "为什么存储高度",
          "blockIds": ["ns-callout"]
        },
        {
          "label": "代码定义",
          "blockIds": ["ns-code"]
        }
      ]
    }
  }
}
